function prepareNightInputs487(){
  const q=emptyNightInputs487();q.day=day;
  for(const i of tickRoad){const t=tiles[i];if(!t||!t.road)continue;const rc=clamp((t.rc||2),1,5);q.roadTiles++;q.roadWeight+=[0,.55,.78,1.04,1.36,1.78][rc];if(t.bus)q.transitNodes++;if(t.rail||t.tram)q.transitNodes+=.35;}
  for(const i of tickBld){const b=tiles[i]&&tiles[i].bld;if(!b||b.ref)continue;const k=b.k|0,cat=kcatOf(k),sz=Math.max(1,b.sz||1),area=Math.min(9,sz*sz);
    if(cat==='R')q.residential+=area;else if(cat==='C')q.commercial+=area;else if(cat==='I'||cat==='E')q.industrial+=area;else if(['A','S','H','D','T'].includes(cat))q.civic+=area;
    if(NIGHT_ENTERTAIN_K487.has(k))q.entertainment+=area;if(NIGHT_TRANSIT_K487.has(k))q.transitNodes+=Math.max(1,sz);if(cat==='G')q.parks+=area;
  }
  q.lightingEvening=+(q.roadWeight*.014+q.transitNodes*.045+q.civic*.010).toFixed(3);
  q.lightingNight=+(q.roadWeight*.021+q.transitNodes*.065+q.civic*.014+(pol&&pol.parkNight?q.parks*.035:0)).toFixed(3);
  nightInputs487=q;return q;
}

